# A /vision world generated by a script: one picture of a neural network reading a handwritten 7,
# learning from its mistake -- and a tour of stops that flies the camera through it.
#   python3 neural-network.py > see-nn.json && python3 build.py see-nn.json
import json, math, random

R = random.Random(7)
DIGIT = ["0111110",
         "0000010",
         "0000100",
         "0001000",
         "0010000",
         "0010000",
         "0010000"]
PIX = [[(0.85 + 0.15 * R.random()) if c == "1" else 0.04 * R.random() for c in row] for row in DIGIT]
X = {"image": -2.75, 0: -1.6, 1: -0.5, 2: 0.55, 3: 1.6}        # where each stage sits along the flow


def sheet(n, gap):  # an n×n layer standing in the y-z plane, facing the flow
    return [(0, (n - 1) / 2 * gap - r * gap, c * gap - (n - 1) / 2 * gap) for r in range(n) for c in range(n)]


LAYERS = [[(X[0], y, z) for _, y, z in sheet(7, 0.15)],
          [(X[1], y, z) for _, y, z in sheet(4, 0.26)],
          [(X[2], y, z) for _, y, z in sheet(4, 0.26)],
          [(X[3], 0.54 - i * 0.12, 0) for i in range(10)]]
NAMES = ["input layer", "hidden layer 1", "hidden layer 2", "output layer"]
W = [[[R.gauss(0, 1) for _ in LAYERS[l + 1]] for _ in LAYERS[l]] for l in range(3)]
PROBS = [0.02, 0.05, 0.03, 0.04, 0.01, 0.03, 0.02, 0.70, 0.03, 0.07]
NEURON = 5  # the hidden neuron we open up


def neuron_detail():
    """One neuron, opened: weighted inputs in, a sum with its bias, the ReLU bend, the output out."""
    s = 0.1
    relu = [[-0.055, -0.03, 0.012], [0.0, -0.03, 0.012], [0.05, 0.035, 0.012]]
    return [
        {"type": "cylinder", "radius": 0.85 * s, "height": 0.25 * s, "rot": [90, 0, 0], "tone": -0.35, "label": "weighted sum"},
        {"type": "glyph", "char": "Σ", "size": 0.75 * s, "depth": 0.08 * s, "at": [0, 0, 0.13 * s], "tone": 1, "contrast": 0},
        {"type": "tube", "from": [0, 0.85 * s, 0], "to": [0, 1.25 * s, 0], "radius": 0.06 * s},
        {"type": "sphere", "radius": 0.18 * s, "at": [0, 1.4 * s, 0], "id": "bias", "label": "bias b"},
        {"type": "arrow", "from": [0.88 * s, 0, 0], "to": [1.35 * s, 0, 0], "radius": 0.05 * s},
        {"type": "group", "id": "activation", "label": "ReLU", "at": [2.0 * s, 0, 0], "parts": [
            {"type": "box", "size": [1.2 * s, 0.95 * s, 0.1 * s], "round": 0.08 * s, "tone": -0.55},
            {"type": "curve", "id": "relu", "path": relu, "radius": 0.06 * s, "smooth": False, "tone": 0.8},
            {"type": "note", "text": "a = max(0, z)", "size": 0.16 * s, "at": [0, -0.72 * s, 0.05 * s]}]},
        {"type": "arrow", "from": [2.65 * s, 0, 0], "to": [3.3 * s, 0, 0], "radius": 0.05 * s},
        {"type": "note", "text": "z = Σ wᵢ·xᵢ + b", "size": 0.2 * s, "at": [0, -1.15 * s, 0.05 * s], "weight": "bold"},
    ]


def layer(l):
    nodes = []
    for i, (x, y, z) in enumerate(LAYERS[l]):
        n = {"type": "sphere", "radius": 0.045 if l == 0 else 0.07 if l < 3 else 0.05, "at": [x, y, z]}
        if l == 0:
            n["tone"] = 0.7 * PIX[i // 7][i % 7] - 0.35       # lit by its pixel
        if l == 1 and i == NEURON:
            n.update({"id": "neuron", "zoom": neuron_detail()})
        if l == 3:
            n["id"] = f"out-{i}"
        nodes.append(n)
    return {"type": "group", "id": f"layer-{l}", "label": NAMES[l], "parts": nodes}


def weights(l):
    tubes = []
    for i, a in enumerate(LAYERS[l]):
        for j, b in enumerate(LAYERS[l + 1]):
            w = W[l][i][j] * (1.6 if l == 0 and PIX[i // 7][i % 7] > 0.5 else 1)
            tubes.append({"type": "tube", "from": list(a), "to": list(b), "radius": 0.0012 + 0.0016 * min(2.5, abs(w)),
                          "tone": 0.3 if w > 0 else -0.45})
    return {"type": "group", "id": f"weights-{l}", "parts": tubes}


def image():
    px, cells, notes = 0.1, [], []
    for r in range(7):
        for c in range(7):
            v = PIX[r][c]
            at = [(c - 3) * px, (3 - r) * px, 0]
            cells.append({"type": "box", "size": [px * 0.92, px * 0.92, 0.03 + 0.05 * v], "at": [at[0], at[1], 0.025 * v], "tone": 1.1 * v - 0.6})
            notes.append({"type": "note", "text": f"{v:.2f}", "size": 0.022, "at": [at[0], at[1], 0.09]})
    return {"type": "group", "id": "image", "label": "the image: 7×7 pixels", "at": [X["image"], 0, 0], "rot": [0, 25, 0],
            "parts": [{"type": "box", "size": [0.78, 0.78, 0.02], "round": 0.02, "at": [0, 0, -0.02], "tone": -0.6}] + cells + notes}


def outputs():
    bars, digits = [], []
    for i, p in enumerate(PROBS):
        y = LAYERS[3][i][1]
        bar = {"type": "box", "size": [0.04 + 0.75 * p, 0.075, 0.05], "at": [1.72 + (0.04 + 0.75 * p) / 2, y, 0], "tone": 0.2}
        if i == 7:
            bar["id"] = "p7"
        bars.append(bar)
        digits.append({"type": "note", "text": str(i), "size": 0.06, "at": [1.67, y, 0.04], "weight": "bold"})
        digits.append({"type": "note", "text": f"{p:.2f}", "size": 0.038, "at": [1.82 + 0.75 * p, y, 0.04], "align": "left"})
    softmax = {"type": "group", "id": "softmax", "label": "softmax: probabilities", "parts": bars + digits}
    target = {"type": "group", "id": "target", "label": "the answer: 7", "parts": [
        {"type": "box", "size": [0.04 + (0.6 if i == 7 else 0), 0.075, 0.05], "at": [2.75 + (0.04 + (0.6 if i == 7 else 0)) / 2, LAYERS[3][i][1], 0], "tone": -0.2}
        for i in range(10)]}
    loss = {"type": "group", "id": "loss", "label": "loss", "at": [3.95, 0.0, 0], "parts": [
        {"type": "box", "size": [0.62, 0.46, 0.06], "round": 0.04, "tone": -0.5},
        {"type": "note", "text": "L = −log p₇", "size": 0.06, "at": [0, 0.07, 0.05], "weight": "bold"},
        {"type": "note", "text": "= −log 0.70 = 0.36", "size": 0.045, "at": [0, -0.07, 0.05]}]}
    return [softmax, target, loss,
            {"type": "link", "id": "to-loss", "from": "softmax", "to": "loss", "radius": 0.012},
            {"type": "link", "id": "answer-to-loss", "from": "target", "to": "loss", "radius": 0.012, "bend": 0.25}]


def descent():
    """The loss over two of the weights: a bowl, and the path the weights take down it."""
    f = lambda a, b: 0.55 * (0.5 * a * a + 0.9 * b * b) + 0.06 * math.sin(3 * a) * math.cos(2 * b)
    path, a, b = [], -1.0, 0.85
    for _ in range(26):  # real gradient steps
        path.append([a, -2.3 + f(a, b) + 0.05, b])
        ga = 0.55 * a + 0.18 * math.cos(3 * a) * math.cos(2 * b)
        gb = 0.99 * b - 0.12 * math.sin(3 * a) * math.sin(2 * b)
        a, b = a - 0.32 * ga, b - 0.32 * gb
    return {"type": "group", "id": "descent", "label": "the loss, over two weights", "at": [0.4, 0, 0], "parts": [
        {"type": "surface", "x": "2.4*(u-0.5)", "z": "2.0*(v-0.5)",
         "y": "-2.3+0.55*(0.5*pow(2.4*(u-0.5),2)+0.9*pow(2.0*(v-0.5),2))+0.06*sin(3*2.4*(u-0.5))*cos(2*2.0*(v-0.5))", "tone": -0.3},
        {"type": "curve", "id": "steps", "path": path, "radius": 0.016, "smooth": False, "label": "gradient steps"},
        {"type": "sphere", "radius": 0.06, "at": path[0], "id": "start", "label": "untrained"},
        {"type": "sphere", "radius": 0.06, "at": path[-1], "id": "end", "label": "trained"},
        {"type": "note", "text": "w ← w − η · ∂L/∂w", "size": 0.07, "at": [0, -1.45, -1.05], "weight": "bold"}]}


world = [
    image(),
    {"type": "link", "id": "flatten", "from": "image", "to": "layer-0", "radius": 0.02, "label": "flatten"},
    {"type": "group", "id": "network", "parts": [weights(0), weights(1), weights(2)] + [layer(l) for l in range(4)]},
    *outputs(),
    {"type": "curve", "id": "backprop", "label": "backpropagation", "radius": 0.022,
     "path": [[3.95, -0.32, 0], [3.2, -0.95, 0.2], [1.5, -1.05, 0.5], [-0.5, -1.0, 0.6], [-1.6, -0.7, 0.4]]},
    {"type": "cone", "radius": 0.06, "height": 0.14, "at": [-1.62, -0.66, 0.38], "rot": [0, 0, 58], "id": "backprop-head"},
    descent(),
]

flow = lambda d, rev=False, p=2.6: {"type": "flow", "period": p, "delay": d, "reverse": rev, "strength": 0.8}
stops = [
    {"caption": "One picture: a network reading a handwritten 7", "view": {"yaw": 28, "pitch": 14},
     "detail": "Everything a small network does is in this one model: the image, four layers of neurons, the 1,072 weights between them, the answer, the loss, and the slope it learns down.",
     "points": ["Left to right: **forward** -- the guess", "Right to left, underneath: **backward** -- the correction", "Below: the **loss surface** the weights roll down"]},
    {"caption": "The input is just numbers, one per pixel", "focus": "image", "view": {"yaw": 22, "pitch": 6},
     "detail": "A picture is a grid of brightness values. Dark is 0, ink is near 1. The network never sees a 7 -- only these 49 numbers.",
     "points": ["7 × 7 = **49** inputs", "Each value `x` is between 0 and 1"]},
    {"caption": "Each pixel drives one input neuron", "focus": "layer-0", "highlight": "flatten", "view": {"yaw": -58, "pitch": 14},
     "detail": "The grid is laid out as 49 input neurons. Each one simply holds its pixel's value: the bright ones are the stroke of the 7.",
     "points": ["Input neurons do no math", "Brighter sphere = larger value"]},
    {"caption": "Every input connects to every hidden neuron", "focus": ["layer-0", "layer-1"], "view": {"yaw": 40, "pitch": 12},
     "animate": {"weights-0": flow(0)},
     "detail": "Each line is one weight: a number the network learns. 49 inputs × 16 hidden neurons = 784 weights in this layer alone.",
     "points": ["Thicker line = larger weight", "Dark = positive, light = negative", "The signal travels along every line at once"]},
    {"caption": "Up close, one neuron weighs, sums and adds a bias", "focus": "neuron", "view": {"yaw": 4, "pitch": 4},
     "detail": "Zoom into any hidden neuron and it opens. Every incoming signal is multiplied by its weight, the products are added up, and the neuron's own bias is added.",
     "points": ["`z = Σ wᵢ·xᵢ + b`", "The bias shifts how easily it fires"]},
    {"caption": "...then bends the sum through an activation", "focus": "activation", "view": {"yaw": 4, "pitch": 4}, "highlight": "relu",
     "detail": "ReLU passes positive sums through and turns negative ones into zero. Without this bend, all the layers together would collapse into one straight-line function.",
     "points": ["`a = max(0, z)`", "This output becomes an input to the next layer"]},
    {"caption": "The forward pass: layer after layer", "focus": "network", "view": {"yaw": 30, "pitch": 12},
     "animate": {"weights-0": flow(0), "weights-1": flow(0.6), "weights-2": flow(1.2)},
     "detail": "Every neuron in a layer does the same weigh-sum-bend at once, and its outputs feed the next layer. The 7's stroke becomes edges, then shapes, then a vote for a digit.",
     "points": ["Layer 1 finds strokes", "Layer 2 combines them into parts of digits", "The output layer scores all ten digits"]},
    {"caption": "Softmax turns ten scores into probabilities", "focus": "softmax", "highlight": "p7", "view": {"yaw": 8, "pitch": 6},
     "detail": "The ten raw scores are exponentiated and divided by their total, so they become probabilities that add up to 1. Here the network is 70% sure it sees a 7.",
     "points": ["`pₖ = e^zₖ / Σ e^zⱼ`", "The guess is the largest: **7**, at 0.70"]},
    {"caption": "The loss measures how wrong the guess was", "focus": ["softmax", "target", "loss"], "highlight": "loss",
     "animate": {"to-loss": flow(0, False, 2.0), "answer-to-loss": flow(0.3, False, 2.0)}, "view": {"yaw": 8, "pitch": 6},
     "detail": "We know the right answer is 7. Cross-entropy loss is the negative log of the probability given to it: 0 if the network was certain, large if it was confidently wrong.",
     "points": ["`L = −log p₇ = 0.36`", "Training means making this number small, over many images"]},
    {"caption": "Backpropagation sends the blame backward", "focus": ["network", "loss", "backprop"], "highlight": ["backprop", "backprop-head"],
     "animate": {"backprop": flow(0, False, 2.2), "weights-2": flow(0.5, True), "weights-1": flow(1.1, True), "weights-0": flow(1.7, True)},
     "view": {"yaw": 24, "pitch": 18},
     "detail": "The chain rule works out, for every one of the 1,072 weights, how much nudging it would change the loss: its gradient. It starts at the loss and flows back, layer by layer.",
     "points": ["`∂L/∂w` for every weight", "Computed in one backward sweep, reusing each layer's results"]},
    {"caption": "Gradient descent: every weight steps downhill", "focus": "descent", "highlight": "end",
     "animate": {"steps": flow(0, False, 2.4)}, "view": {"yaw": 20, "pitch": 32},
     "detail": "Picture the loss as a landscape over the weights (here, just two of them). Each step moves the weights a little against the gradient, so the loss goes down.",
     "points": ["`w ← w − η · ∂L/∂w`", "`η`, the learning rate, sets the step size"]},
    {"caption": "Millions of images later, it reads digits", "view": {"yaw": 28, "pitch": 14},
     "detail": "Forward, measure, backward, step -- repeated over a whole dataset. No rule for '7' is ever written down: it ends up encoded in the weights.",
     "points": ["One loop: forward → loss → backward → step"]},
]

print(json.dumps({"title": "How a neural network learns", "detail": "max", "world": world, "stops": stops,
                  "summary": "A neural network is layers of simple units. Each **neuron** multiplies its inputs by **weights**, adds a **bias**, "
                             "and bends the sum with an **activation** like ReLU.\n\n"
                             "- **Forward**: the image's numbers flow through the layers to ten scores; **softmax** makes them probabilities.\n"
                             "- **Loss**: cross-entropy says how wrong the guess was: `−log p(correct)`.\n"
                             "- **Backward**: backpropagation finds every weight's gradient `∂L/∂w`.\n"
                             "- **Step**: gradient descent nudges each weight downhill: `w ← w − η·∂L/∂w`.\n\n"
                             "Repeat over many examples, and what the network knows ends up in its weights."}, ensure_ascii=False))
